use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let (first, rest) = match input.find('\n') {
        Some(i) => (&input[..i], &input[i + 1..]),
        None => (&input[..], ""),
    };
    let w = match first.trim().parse::<usize>() {
        Ok(w) if w > 0 => w,
        _ => {
            println!("error: bad width");
            std::process::exit(1);
        }
    };
    let mut out = String::new();
    let mut line = String::new();
    let mut len = 0usize;
    for word in rest.split_whitespace() {
        let wl = word.chars().count();
        if len == 0 {
            line.push_str(word);
            len = wl;
        } else if len + 1 + wl <= w {
            line.push(' ');
            line.push_str(word);
            len += 1 + wl;
        } else {
            out.push_str(&line);
            out.push('\n');
            line.clear();
            line.push_str(word);
            len = wl;
        }
    }
    if len > 0 {
        out.push_str(&line);
        out.push('\n');
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
}

